.darma-loader-darma-b13-sticky-note-peel { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #fde047); width: calc(var(--loader-size, 108px) * .84); height: calc(var(--loader-size, 108px) * .84); position: relative; perspective: 420px; }
.darma-loader-darma-b13-sticky-note-peel::after { content: ''; position: absolute; inset: 0; border-radius: 2px; background: color-mix(in srgb, #000 18%, var(--accent-2)); }
.darma-loader-darma-b13-sticky-note-peel span { position: absolute; inset: 0; border-radius: 2px; transform-origin: top center; background: linear-gradient(var(--accent-2), var(--accent)); box-shadow: 0 3px 8px rgba(15, 23, 42, .2); animation: darma-loader-darma-b13-sticky-note-peel-peel calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b13-sticky-note-peel span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * -1.1); }
.darma-loader-darma-b13-sticky-note-peel span::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 26%; background: linear-gradient(rgba(255, 255, 255, .42), transparent); }
@keyframes darma-loader-darma-b13-sticky-note-peel-peel { 0% { opacity: 1; transform: rotateX(0deg) translateY(0); } 52% { opacity: 1; transform: rotateX(-74deg) translateY(-14%); } 82% { opacity: .28; transform: rotateX(-112deg) translateY(-42%); } 100% { opacity: 0; transform: rotateX(-112deg) translateY(-42%); } }

